head.script:
scwin.screenId = "jldfil15300";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_corpUsrTpCd", fn: function(){ return (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.corpUsrTpCd", unresolved: "session:" + "corpUsrTpCd" }; })())($c.session.getUserInfo("corpUsrTpCd")) !== '19'); } }, { id: "tr_28", fn: function(){ return (((sv) => (sv !== undefined && sv !== null) ? sv : (() => { throw { bizMessage: "세션 값을 읽지 못했습니다 — " + "session.user.corpUsrTpCd", unresolved: "session:" + "corpUsrTpCd" }; })())($c.session.getUserInfo("corpUsrTpCd")) !== '19'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("keyword"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_FileDown();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil15300.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_35_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_35_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_35_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15300.img_35_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_lawList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_lawList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_lawList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_lawList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["eixstLawBinfile"] === 'Y') { if (typeof scwin.fileDown === 'function') { await scwin.fileDown(r["lawNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.fileDown (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fileDown'); } return; }
        if (typeof scwin.viewLawItem === 'function') { await scwin.viewLawItem(r["lawNo"], r["lawTitle"], r["dtruleLawNo"], r["lawAmendDd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewLawItem (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewLawItem'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_lawList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_ViewLawItem
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ViewLawItem = async function () {
    const sbmOptions = {
        id: "tx_fn_ViewLawItem",
        method: "post",
        action: "/support/law.do",
        ref: "dma_ViewLawItemReq",
        target: "dlt_lawList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil15300.tx_fn_ViewLawItem" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/support/law.do",
        ref: "dma_SearchReq",
        target: "dlt_lawList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil15300.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_FileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/support/law.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.viewLawItem
 * @author Inswave
 * @date 2026. 09. 29
 * @param _lawNo _lawTitle _dtruleLawNo _lawAmendDd
 * @returns
 * @hidden N
*/
scwin.viewLawItem = async function (_lawNo, _lawTitle, _dtruleLawNo, _lawAmendDd) {
    /* sdd-asis-lifecycle:begin fn_ViewLawItem — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.lawForm || { elements: [] });
    $c.util.getComponent('dma_ViewLawItemReq').set('lawNo', _lawNo);
    $c.util.getComponent('dma_ViewLawItemReq').set('lawTitle', _lawTitle);
    $c.util.getComponent('dma_ViewLawItemReq').set('dtruleLawNo', _dtruleLawNo);
    $c.util.getComponent('dma_ViewLawItemReq').set('lawAmendDd', _lawAmendDd);
    $c.util.getComponent('dma_ViewLawItemReq').set('method', "searchLawItem");
    frm.action = "law.do";
    { const nr = await scwin.tx_fn_ViewLawItem(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil15301/jldfil15301.xml", { "lawNo": _lawNo, "lawTitle": _lawTitle, "dtruleLawNo": _dtruleLawNo, "lawAmendDd": _lawAmendDd, "method": "searchLawItem" }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.lawSearchForm || { elements: [] });
    if (($c.util.getComponent('ipt_keyword').getValue() == null ? '' : String($c.util.getComponent('ipt_keyword').getValue())) === '') {
        await $c.win.alert('검색할 단어를 입력하세요');
        return;
    }
    $c.util.getComponent('dma_ViewLawItemReq').set('method', "searchLawByKeyword");
    frm.action = "law.do";
    { const nr = await scwin.tx_fn_Search(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil15303/jldfil15303.xml", { "method": "searchLawByKeyword" }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param _lawNo
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (_lawNo) {
    /* sdd-asis-lifecycle:begin fn_FileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.fileDownForm || { elements: [] });
    $c.util.getComponent('dma_ViewLawItemReq').set('method', "downLawFile");
    $c.util.getComponent('dma_ViewLawItemReq').set('lawNo', _lawNo);
    frm.action = "law.do";
    await scwin.tx_fn_FileDown();
    /* sdd-asis-lifecycle:end */
};
